1	//! 레코드 검사(계약 3절)와 CSV·JSON Lines 읽기(계약 2절).
2	
3	use crate::csv;
4	use crate::json::{self, Parsed, Value};
5	use crate::ts;
6	
7	pub const FIELDS: [&str; 6] = ["ts", "method", "path", "status", "bytes", "latency_ms"];
8	const MAX_BYTES: i64 = 1_000_000_000_000;
9	const MAX_LATENCY_MS: f64 = 1e9;
10	const METHODS: [&str; 7] = ["GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"];
11	
12	#[derive(Debug, Clone, PartialEq)]
13	pub struct Record {
14	    /// UTC 마이크로초(ts.rs)
15	    pub ts: i64,
16	    pub method: &'static str,
17	    /// WTF-8 바이트(JSON 의 짝 없는 서로게이트 포함). 바이트 순서 = 코드 포인트 순서
18	    pub path: Vec<u8>,
19	    pub status: i64,
20	    pub bytes: i64,
21	    pub latency_ms: f64,
22	}
23	
24	/// (레코드 번호, 레코드 또는 이유 문자열)
25	pub type Row = (usize, Result<Record, String>);
26	
27	fn bad(reason: &str) -> String {
28	    reason.to_string()
29	}
30	
31	fn method(s: &[u8]) -> Result<&'static str, String> {
32	    METHODS
33	        .iter()
34	        .find(|m| m.as_bytes() == s)
35	        .copied()
36	        .ok_or_else(|| bad("bad method"))
37	}
38	
39	fn timestamp(s: &[u8]) -> Result<i64, String> {
40	    ts::parse(s).ok_or_else(|| bad("bad ts"))
41	}
42	
43	fn path(s: &[u8]) -> Result<Vec<u8>, String> {
44	    if s.first() != Some(&b'/') {
45	        return Err(bad("bad path"));
46	    }
47	    let end = s.iter().position(|&c| c == b'?').unwrap_or(s.len());
48	    Ok(s[..end].to_vec())
49	}
50	
51	fn all_digits(s: &str) -> bool {
52	    !s.is_empty() && s.bytes().all(|c| c.is_ascii_digit())
53	}
54	
55	/// CSV 한 행. `get` 은 필드 이름으로 값을 준다.
56	fn record_from_strings<'a>(get: impl Fn(&str) -> &'a str) -> Result<Record, String> {
57	    let method = method(get("method").as_bytes())?;
58	    let status = get("status").as_bytes();
59	    if !(status.len() == 3
60	        && (b'1'..=b'5').contains(&status[0])
61	        && status[1..].iter().all(u8::is_ascii_digit))
62	    {
63	        return Err(bad("bad status"));
64	    }
65	    let raw_bytes = get("bytes");
66	    let digits = match raw_bytes.trim_start_matches('0') {
67	        "" => "0",
68	        d => d,
69	    };
70	    if !all_digits(raw_bytes) || digits.len() > 13 {
71	        return Err(bad("bad bytes"));
72	    }
73	    let size: i64 = digits.parse().map_err(|_| bad("bad bytes"))?;
74	    if size > MAX_BYTES {
75	        return Err(bad("bad bytes"));
76	    }
77	    let raw_latency = get("latency_ms");
78	    let latency_ok = match raw_latency.split_once('.') {
79	        None => all_digits(raw_latency),
80	        Some((int, frac)) => all_digits(int) && all_digits(frac),
81	    };
82	    let latency: f64 = if latency_ok {
83	        raw_latency.parse().map_err(|_| bad("bad latency_ms"))?
84	    } else {
85	        return Err(bad("bad latency_ms"));
86	    };
87	    if latency > MAX_LATENCY_MS {
88	        return Err(bad("bad latency_ms"));
89	    }
90	    Ok(Record {
91	        ts: timestamp(get("ts").as_bytes())?,
92	        method,
93	        path: path(get("path").as_bytes())?,
94	        status: i64::from(status[0] - b'0') * 100
95	            + i64::from(status[1] - b'0') * 10
96	            + i64::from(status[2] - b'0'),
97	        bytes: size,
98	        latency_ms: latency,
99	    })
100	}
101	
102	fn record_from_json(obj: &[(Vec<u8>, Value)]) -> Result<Record, String> {
103	    for name in FIELDS {
104	        if json::get(obj, name).is_none() {
105	            return Err(format!("missing field: {name}"));
106	        }
107	    }
108	    let field = |name: &str| json::get(obj, name).unwrap_or(&Value::Null);
109	    let method = match field("method") {
110	        Value::Str(s) => method(s)?,
111	        _ => return Err(bad("bad method")),
112	    };
113	    let status = match field("status") {
114	        Value::Int(Some(v)) if (100..=599).contains(v) => *v,
115	        _ => return Err(bad("bad status")),
116	    };
117	    let size = match field("bytes") {
118	        Value::Int(Some(v)) if (0..=MAX_BYTES).contains(v) => *v,
119	        _ => return Err(bad("bad bytes")),
120	    };
121	    let latency = match field("latency_ms") {
122	        Value::Int(Some(v)) if (0..=1_000_000_000).contains(v) => *v as f64,
123	        // NaN 은 비교가 모두 거짓이라 여기서 걸린다. -0.0 은 통과하고 부호를 유지한다
124	        Value::Float(x) if 0.0 <= *x && *x <= MAX_LATENCY_MS => *x,
125	        _ => return Err(bad("bad latency_ms")),
126	    };
127	    let ts = match field("ts") {
128	        Value::Str(s) => timestamp(s)?,
129	        _ => return Err(bad("bad ts")),
130	    };
131	    let path = match field("path") {
132	        Value::Str(s) => path(s)?,
133	        _ => return Err(bad("bad path")),
134	    };
135	    Ok(Record {
136	        ts,
137	        method,
138	        path,
139	        status,
140	        bytes: size,
141	        latency_ms: latency,
142	    })
143	}
144	
145	/// (레코드 목록, 파일 전체를 거부하는 오류 메시지). 오류가 나도 그 앞까지 읽은 레코드는 돌려준다.
146	pub fn read_csv(text: &str) -> (Vec<Row>, Option<String>) {
147	    let mut reader = csv::Reader::new(text);
148	    let header = match reader.next() {
149	        None => return (Vec::new(), None),
150	        Some(Err(_)) => return (Vec::new(), Some("header: csv field too large".to_string())),
151	        Some(Ok(h)) => h,
152	    };
153	    // 같은 이름이 두 번 나오면 뒤의 열(dict(zip(header, row)))
154	    let mut index = [0usize; 6];
155	    for (slot, name) in index.iter_mut().zip(FIELDS) {
156	        match header.iter().rposition(|h| h == name) {
157	            Some(i) => *slot = i,
158	            None => return (Vec::new(), Some(format!("missing column: {name}"))),
159	        }
160	    }
161	    let mut out = Vec::new();
162	    let mut number = 0;
163	    for row in reader {
164	        let row = match row {
165	            Ok(row) => row,
166	            Err(_) => {
167	                return (
168	                    out,
169	                    Some(format!("record {}: csv field too large", number + 1)),
170	                )
171	            }
172	        };
173	        if row.is_empty() {
174	            continue;
175	        }
176	        number += 1;
177	        if row.len() != header.len() {
178	            out.push((number, Err(bad("bad field count"))));
179	            continue;
180	        }
181	        let get = |name: &str| {
182	            let i = FIELDS.iter().position(|f| *f == name).unwrap_or(0);
183	            row[index[i]].as_str()
184	        };
185	        out.push((number, record_from_strings(get)));
186	    }
187	    (out, None)
188	}
189	
190	pub fn read_jsonl(text: &str) -> Vec<Row> {
191	    let mut out = Vec::new();
192	    let mut number = 0;
193	    // splitlines() 가 아니라 split('\n'): U+2028 등에서 나누지 않는다
194	    for line in text.split('\n') {
195	        if line.bytes().all(|b| matches!(b, b' ' | b'\t' | b'\r')) {
196	            continue;
197	        }
198	        number += 1;
199	        let item = match json::loads(line) {
200	            Err(_) => Err(bad("invalid json")),
201	            Ok(Parsed::NotObject) => Err(bad("not an object")),
202	            Ok(Parsed::Object(obj)) => record_from_json(&obj),
203	        };
204	        out.push((number, item));
205	    }
206	    out
207	}
