90	                Some(ch) => self.add_char(ch)?,
91	            },
92	            State::QuoteInQuotedField => {
93	                if c == Some('"') {
94	                    self.add_char('"')?;
95	                    self.state = State::InQuotedField;
96	                } else if c == Some(',') {
97	                    self.save_field();
98	                    self.state = State::StartField;
99	                } else if newline_or_eol {
100	                    self.save_field();
101	                    self.state = after_line;
102	                } else if let Some(ch) = c {
103	                    // strict=False: 닫는 따옴표 뒤의 글자는 필드에 이어 붙인다
104	                    self.add_char(ch)?;
105	                    self.state = State::InField;
106	                }
107	            }
108	            State::EatCrnl => {
109	                if c.is_none() {
110	                    self.state = State::StartRecord;
111	                }
112	                // 줄을 \r, \n 에서만 나누므로 줄바꿈 뒤에 다른 글자가 오는 일은 없다
113	            }
