119	pub struct Reader<'a> {
120	    text: &'a str,
121	    pos: usize,
122	}
123	
124	impl<'a> Reader<'a> {
125	    pub fn new(text: &'a str) -> Self {
126	        Reader { text, pos: 0 }
127	    }
128	
129	    /// StringIO(newline="") 의 readline: 줄 끝 문자를 포함해 돌려준다.
130	    fn next_line(&mut self) -> Option<&'a str> {
131	        let rest = &self.text[self.pos..];
132	        if rest.is_empty() {
133	            return None;
134	        }
135	        let bytes = rest.as_bytes();
136	        let end = match bytes.iter().position(|&b| b == b'\n' || b == b'\r') {
137	            None => bytes.len(),
138	            Some(i) if bytes[i] == b'\r' && bytes.get(i + 1) == Some(&b'\n') => i + 2,
139	            Some(i) => i + 1,
140	        };
141	        self.pos += end;
142	        Some(&rest[..end])
143	    }
144	}
145	
146	impl Iterator for Reader<'_> {
147	    type Item = Result<Vec<String>, FieldTooLarge>;
148	
149	    fn next(&mut self) -> Option<Self::Item> {
150	        let mut p = Parse {
151	            state: State::StartRecord,
152	            fields: Vec::new(),
153	            field: String::new(),
154	            field_len: 0,
155	        };
156	        loop {
157	            let Some(line) = self.next_line() else {
158	                // 입력 끝: 인용이 안 닫혔거나 필드가 남아 있으면 그때까지를 필드로 저장한다
159	                if p.field_len != 0 || p.state == State::InQuotedField {
160	                    p.save_field();
161	                    return Some(Ok(p.fields));
162	                }
163	                return None;
164	            };
165	            for c in line.chars() {
166	                if let Err(e) = p.process(Some(c)) {
167	                    self.pos = self.text.len();
168	                    return Some(Err(e));
169	                }
170	            }
171	            if let Err(e) = p.process(None) {
172	                self.pos = self.text.len();
173	                return Some(Err(e));
174	            }
175	            if p.state == State::StartRecord {
176	                return Some(Ok(p.fields));
177	            }
178	        }
179	    }
180	}
181	
182	#[cfg(test)]
183	mod tests {
184	    use super::*;
185	
186	    fn rows(text: &str) -> Vec<Vec<String>> {
187	        Reader::new(text).map(|r| r.unwrap()).collect()
188	    }
