192	        // 기대값은 verify/probe.py 로 Python 3.12.3 에서 얻었다
193	        assert_eq!(rows("a\0b,c\n"), vec![vec!["a\0b", "c"]]);
194	        assert_eq!(rows("\"ab\"cd,x\n"), vec![vec!["abcd", "x"]]);
195	        assert_eq!(rows("a\"b,x\n"), vec![vec!["a\"b", "x"]]);
196	        assert_eq!(rows(" \"a\" ,x\n"), vec![vec![" \"a\" ", "x"]]);
197	        assert_eq!(rows("\"abc"), vec![vec!["abc"]]);
198	        assert_eq!(rows("a\rb\r\nc\n"), vec![vec!["a"], vec!["b"], vec!["c"]]);
199	        assert_eq!(rows("\"a\rb\"\n"), vec![vec!["a\rb"]]);
200	        assert_eq!(rows("\"\"\n"), vec![vec![""]]);
201	        assert_eq!(rows("\n\n"), vec![Vec::<String>::new(), vec![]]);
202	        assert_eq!(rows("\"a\"\"b\",c"), vec![vec!["a\"b", "c"]]);
203	        assert_eq!(rows("x,\""), vec![vec!["x", ""]]);
204	        assert_eq!(rows("a,\n"), vec![vec!["a", ""]]);
205	        assert_eq!(rows(",\n"), vec![vec!["", ""]]);
206	        assert!(rows("").is_empty());
207	    }
208	
209	    #[test]
210	    fn field_limit_counts_code_points() {
211	        let ok = "가".repeat(FIELD_LIMIT);
212	        assert_eq!(rows(&ok)[0][0].chars().count(), FIELD_LIMIT);
213	        let bad = "가".repeat(FIELD_LIMIT + 1);
214	        assert_eq!(Reader::new(&bad).next(), Some(Err(FieldTooLarge)));
215	        let quoted = format!("\"{}\"\"\"", "x".repeat(FIELD_LIMIT - 1));
216	        assert_eq!(rows(&quoted)[0][0].len(), FIELD_LIMIT);
217	    }
218	}
