10	/// Python 3.12.3 에서 측정한 중첩 한도(바깥 객체 포함). 계약 2.2절, verify/probe.py.
11	pub const MAX_DEPTH: usize = 9997;
12	/// `sys.get_int_max_str_digits()` 기본값.
13	pub const MAX_INT_DIGITS: usize = 4300;
14	
15	#[derive(Debug, PartialEq, Eq)]
16	pub struct Invalid;
17	
18	#[derive(Debug, Clone, PartialEq)]
19	pub enum Value {
20	    Null,
21	    Bool(bool),
22	    /// 정수. i64 범위를 넘으면 None(이 프로그램의 모든 범위 검사에서 범위 밖)
23	    Int(Option<i64>),
24	    Float(f64),
25	    /// WTF-8 바이트(짝 없는 서로게이트도 3바이트로 담는다)
26	    Str(Vec<u8>),
27	    /// 배열 또는 객체(내용은 쓰지 않는다)
28	    Container,
29	}
30	
31	#[derive(Debug, PartialEq)]
32	pub enum Parsed {
33	    /// 멤버를 나온 순서대로 담는다. 같은 키는 뒤의 것이 이기므로 찾을 때 뒤에서부터 본다.
34	    Object(Vec<(Vec<u8>, Value)>),
35	    NotObject,
36	}
37	
38	pub fn get<'a>(members: &'a [(Vec<u8>, Value)], key: &str) -> Option<&'a Value> {
39	    members
40	        .iter()
41	        .rev()
42	        .find(|(k, _)| k == key.as_bytes())
43	        .map(|(_, v)| v)
44	}
45	
46	pub fn loads(text: &str) -> Result<Parsed, Invalid> {
47	    if text.starts_with('\u{feff}') {
48	        return Err(Invalid);
49	    }
50	    let mut p = Parser {
51	        b: text.as_bytes(),
52	        i: 0,
53	    };
54	    p.ws();
55	    let parsed = match p.peek() {
56	        Some(b'{') => Parsed::Object(p.top_object()?),
57	        Some(b'[') => {
58	            p.skip_container(0)?;
59	            Parsed::NotObject
60	        }
61	        _ => {
62	            p.scalar()?;
63	            Parsed::NotObject
64	        }
65	    };
66	    p.ws();
67	    if p.i != p.b.len() {
68	        return Err(Invalid);
69	    }
70	    Ok(parsed)
71	}
72	
73	struct Parser<'a> {
74	    b: &'a [u8],
75	    i: usize,
76	}
77	
78	fn push_wtf8(out: &mut Vec<u8>, cp: u32) {
79	    if cp < 0x80 {
80	        out.push(cp as u8);
81	    } else if cp < 0x800 {
82	        out.push(0xC0 | (cp >> 6) as u8);
83	        out.push(0x80 | (cp & 0x3F) as u8);
84	    } else if cp < 0x10000 {
85	        out.push(0xE0 | (cp >> 12) as u8);
86	        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
87	        out.push(0x80 | (cp & 0x3F) as u8);
88	    } else {
89	        out.push(0xF0 | (cp >> 18) as u8);
90	        out.push(0x80 | ((cp >> 12) & 0x3F) as u8);
91	        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
92	        out.push(0x80 | (cp & 0x3F) as u8);
93	    }
94	}
95	
96	impl Parser<'_> {
97	    fn peek(&self) -> Option<u8> {
98	        self.b.get(self.i).copied()
99	    }
100	
101	    fn ws(&mut self) {
102	        while matches!(self.peek(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
103	            self.i += 1;
104	        }
105	    }
106	
107	    fn expect(&mut self, c: u8) -> Result<(), Invalid> {
108	        if self.peek() != Some(c) {
109	            return Err(Invalid);
110	        }
111	        self.i += 1;
112	        Ok(())
113	    }
114	
115	    fn digit_at(&self, i: usize) -> bool {
116	        matches!(self.b.get(i), Some(c) if c.is_ascii_digit())
117	    }
118	
119	    fn top_object(&mut self) -> Result<Vec<(Vec<u8>, Value)>, Invalid> {
120	        let mut members = Vec::new();
121	        self.i += 1;
122	        self.ws();
123	        if self.peek() == Some(b'}') {
124	            self.i += 1;
125	            return Ok(members);
126	        }
127	        loop {
128	            let key = self.key()?;
129	            let value = match self.peek() {
130	                Some(b'{' | b'[') => {
131	                    self.skip_container(1)?;
132	                    Value::Container
133	                }
134	                _ => self.scalar()?,
135	            };
136	            members.push((key, value));
137	            self.ws();
138	            match self.peek() {
139	                Some(b'}') => {
140	                    self.i += 1;
141	                    return Ok(members);
142	                }
143	                Some(b',') => {
144	                    self.i += 1;
145	                    self.ws();
146	                }
147	                _ => return Err(Invalid),
148	            }
149	        }
150	    }
151	
152	    /// `"키"` 공백 `:` 공백 까지 읽는다.
153	    fn key(&mut self) -> Result<Vec<u8>, Invalid> {
154	        if self.peek() != Some(b'"') {
155	            return Err(Invalid);
156	        }
157	        let key = self.string()?;
158	        self.ws();
159	        self.expect(b':')?;
160	        self.ws();
161	        Ok(key)
162	    }
163	
164	    /// `{` 또는 `[` 에서 시작하는 값 하나를 끝까지 검사한다. `outer` 는 바깥 중첩 깊이.
165	    fn skip_container(&mut self, outer: usize) -> Result<(), Invalid> {
166	        let mut stack: Vec<u8> = Vec::new();
167	        loop {
168	            // 값 하나를 읽을 차례
169	            match self.peek() {
170	                Some(open @ (b'{' | b'[')) => {
171	                    if outer + stack.len() + 1 > MAX_DEPTH {
172	                        return Err(Invalid);
173	                    }
174	                    self.i += 1;
175	                    self.ws();
176	                    let close = if open == b'{' { b'}' } else { b']' };
177	                    if self.peek() == Some(close) {
178	                        self.i += 1;
179	                    } else {
180	                        stack.push(open);
181	                        if open == b'{' {
182	                            self.key()?;
183	                        }
184	                        continue;
185	                    }
186	                }
187	                _ => {
188	                    self.scalar()?;
189	                }
190	            }
191	            // 값 하나를 다 읽었다: 닫는 괄호 또는 쉼표
192	            loop {
193	                let Some(&top) = stack.last() else {
194	                    return Ok(());
195	                };
196	                self.ws();
197	                let close = if top == b'{' { b'}' } else { b']' };
198	                match self.peek() {
199	                    Some(c) if c == close => {
200	                        self.i += 1;
201	                        stack.pop();
202	                    }
203	                    Some(b',') => {
204	                        self.i += 1;
205	                        self.ws();
206	                        if top == b'{' {
207	                            self.key()?;
208	                        }
209	                        break;
210	                    }
211	                    _ => return Err(Invalid),
212	                }
213	            }
214	        }
215	    }
216	
217	    fn literal(&mut self, word: &str, value: Value) -> Result<Value, Invalid> {
218	        if self.b[self.i..].starts_with(word.as_bytes()) {
219	            self.i += word.len();
220	            Ok(value)
221	        } else {
222	            Err(Invalid)
223	        }
224	    }
225	
226	    fn scalar(&mut self) -> Result<Value, Invalid> {
227	        match self.peek() {
228	            Some(b'"') => Ok(Value::Str(self.string()?)),
229	            Some(b'n') => self.literal("null", Value::Null),
230	            Some(b't') => self.literal("true", Value::Bool(true)),
231	            Some(b'f') => self.literal("false", Value::Bool(false)),
232	            Some(b'N') => self.literal("NaN", Value::Float(f64::NAN)),
233	            Some(b'I') => self.literal("Infinity", Value::Float(f64::INFINITY)),
234	            Some(b'-') if self.b[self.i..].starts_with(b"-Infinity") => {
235	                self.literal("-Infinity", Value::Float(f64::NEG_INFINITY))
236	            }
237	            _ => self.number(),
238	        }
239	    }
240	
241	    /// `-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?`
242	    fn number(&mut self) -> Result<Value, Invalid> {
243	        let start = self.i;
244	        let mut i = self.i;
245	        let negative = self.b.get(i) == Some(&b'-');
246	        if negative {
247	            i += 1;
248	        }
249	        match self.b.get(i) {
250	            Some(b'1'..=b'9') => {
251	                i += 1;
252	                while self.digit_at(i) {
253	                    i += 1;
254	                }
255	            }
256	            Some(b'0') => i += 1,
257	            _ => return Err(Invalid),
258	        }
259	        let int_end = i;
260	        let mut is_float = false;
261	        if self.b.get(i) == Some(&b'.') && self.digit_at(i + 1) {
262	            is_float = true;
263	            i += 2;
264	            while self.digit_at(i) {
265	                i += 1;
266	            }
267	        }
268	        if matches!(self.b.get(i), Some(b'e' | b'E')) {
269	            let e_start = i;
270	            i += 1;
271	            if matches!(self.b.get(i), Some(b'-' | b'+')) {
272	                i += 1;
273	            }
274	            let digits_start = i;
275	            while self.digit_at(i) {
276	                i += 1;
277	            }
278	            if i > digits_start {
279	                is_float = true;
280	            } else {
281	                // 지수가 아니다: 되돌린다(뒤에 남은 'e' 때문에 결국 오류가 된다)
282	                i = e_start;
283	            }
284	        }
285	        self.i = i;
286	        // 숫자 부분은 ASCII 라 문자열 경계가 맞다
287	        let s = std::str::from_utf8(&self.b[start..i]).map_err(|_| Invalid)?;
288	        if is_float {
289	            // Rust 의 parse 는 정확한 반올림이고 넘치면 inf 다(Python PyFloat_FromString 과 같음)
290	            return s.parse::<f64>().map(Value::Float).map_err(|_| Invalid);
291	        }
292	        let digits = int_end - start - usize::from(negative);
293	        if digits > MAX_INT_DIGITS {
294	            return Err(Invalid);
295	        }
296	        Ok(Value::Int(s.parse::<i64>().ok()))
297	    }
298	
299	    fn hex4(&self, at: usize) -> Result<u32, Invalid> {
300	        let h = self.b.get(at..at + 4).ok_or(Invalid)?;
301	        let mut v = 0u32;
302	        for &c in h {
303	            let d = (c as char).to_digit(16).ok_or(Invalid)?;
304	            v = v * 16 + d;
305	        }
306	        Ok(v)
307	    }
308	
309	    /// 여는 `"` 에서 시작해 닫는 `"` 뒤까지 읽는다.
310	    fn string(&mut self) -> Result<Vec<u8>, Invalid> {
311	        let mut out = Vec::new();
312	        self.i += 1;
313	        loop {
314	            let c = self.peek().ok_or(Invalid)?;
315	            match c {
316	                b'"' => {
317	                    self.i += 1;
318	                    return Ok(out);
319	                }
320	                b'\\' => {
321	                    self.i += 1;
322	                    let e = self.peek().ok_or(Invalid)?;
323	                    self.i += 1;
324	                    match e {
325	                        b'"' | b'\\' | b'/' => out.push(e),
326	                        b'b' => out.push(0x08),
327	                        b'f' => out.push(0x0C),
328	                        b'n' => out.push(b'\n'),
329	                        b'r' => out.push(b'\r'),
330	                        b't' => out.push(b'\t'),
331	                        b'u' => {
332	                            let mut cp = self.hex4(self.i)?;
333	                            self.i += 4;
334	                            if (0xD800..=0xDBFF).contains(&cp)
335	                                && self.b[self.i..].starts_with(b"\\u")
336	                            {
337	                                let low = self.hex4(self.i + 2)?;
338	                                if (0xDC00..=0xDFFF).contains(&low) {
339	                                    cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
340	                                    self.i += 6;
341	                                }
342	                            }
343	                            push_wtf8(&mut out, cp);
344	                        }
345	                        _ => return Err(Invalid),
346	                    }
347	                }
348	                0x00..=0x1F => return Err(Invalid),
349	                _ => {
350	                    out.push(c);
351	                    self.i += 1;
352	                }
353	            }
354	        }
355	    }
356	}
357	
358	#[cfg(test)]
359	mod tests {
360	    use super::*;
361	
362	    fn value(s: &str) -> Value {
363	        match loads(&format!("{{\"k\":{s}}}")) {
364	            Ok(Parsed::Object(m)) => m[0].1.clone(),
365	            other => panic!("{s}: {other:?}"),
366	        }
367	    }
368	
369	    #[test]
370	    fn numbers() {
371	        assert_eq!(value("-0"), Value::Int(Some(0)));
372	        assert_eq!(value("1e400"), Value::Float(f64::INFINITY));
373	        assert_eq!(value("-1e400"), Value::Float(f64::NEG_INFINITY));
374	        assert_eq!(
375	            value("1.5e99999999999999999999"),
376	            Value::Float(f64::INFINITY)
377	        );
378	        assert_eq!(value("0.0e-99999999999999999999"), Value::Float(0.0));
379	        assert_eq!(value("99999999999999999999"), Value::Int(None));
380	        match value("-0.0") {
381	            Value::Float(x) => assert!(x == 0.0 && x.is_sign_negative()),
382	            v => panic!("{v:?}"),
383	        }
384	        assert_eq!(value(&"1".repeat(4300)), Value::Int(None));
385	        assert_eq!(value(&format!("-{}", "1".repeat(4300))), Value::Int(None));
386	        assert!(loads(&format!("{{\"k\":{}}}", "1".repeat(4301))).is_err());
387	        assert!(loads(&format!("[{}]", "1".repeat(4301))).is_err());
388	        for bad in [
389	            "01", "1.", ".5", "-", "+1", "-NaN", "1e", "1.e5", "nul", "True",
390	        ] {
391	            assert!(loads(&format!("{{\"k\":{bad}}}")).is_err(), "{bad}");
392	        }
393	    }
394	
395	    #[test]
396	    fn strings() {
397	        assert_eq!(value(r#""\ud800""#), Value::Str(vec![0xED, 0xA0, 0x80]));
398	        assert_eq!(value(r#""𐀀""#), Value::Str("\u{10000}".as_bytes().to_vec()));
399	        assert_eq!(
400	            value(r#""\ud800A""#),
401	            Value::Str(vec![0xED, 0xA0, 0x80, b'A'])
402	        );
403	        assert_eq!(
404	            value("\"a\u{7f}\u{2028}\""),
405	            Value::Str("a\u{7f}\u{2028}".into())
406	        );
407	        assert!(loads("{\"k\":\"a\u{1}\"}").is_err());
408	        assert!(loads(r#"{"k":"\x"}"#).is_err());
409	    }
410	
411	    #[test]
412	    fn structure() {
413	        assert_eq!(loads(" [1, {\"a\": []}] \r"), Ok(Parsed::NotObject));
414	        assert_eq!(loads("1"), Ok(Parsed::NotObject));
415	        assert!(loads("\u{feff}{}").is_err());
416	        assert!(loads("{} x").is_err());
417	        assert!(loads("[1,]").is_err());
418	        assert!(loads("{\"a\":1,}").is_err());
419	        assert!(loads("{\"a\" 1}").is_err());
420	        assert!(loads("\u{c}{}").is_err());
421	        let Ok(Parsed::Object(m)) = loads(r#"{"a":1,"a":2}"#) else {
422	            panic!()
423	        };
424	        assert_eq!(get(&m, "a"), Some(&Value::Int(Some(2))));
425	    }
426	
427	    #[test]
428	    fn depth_limit() {
429	        for (depth, ok) in [(9997, true), (9998, false)] {
430	            let obj = format!("{}1{}", "{\"a\":".repeat(depth), "}".repeat(depth));
431	            assert_eq!(loads(&obj).is_ok(), ok);
432	            let arr = format!("{}{}", "[".repeat(depth), "]".repeat(depth));
433	            assert_eq!(loads(&arr).is_ok(), ok);
434	        }
435	    }
436	}
