                                    self.i += 6;
                                }
                            }
                            push_wtf8(&mut out, cp);
                        }
                        _ => return Err(Invalid),
                    }
                }
                0x00..=0x1F => return Err(Invalid),
                _ => {
                    out.push(c);
                    self.i += 1;
                }
            }
        }
    }
}

